+                                             in_row[x + 2 * Nxy] + in_row[x - 2 * Nxy]) +
+                                  coef[3] * (in_row[x + 3] + in_row[x - 3] + in_row[x + 3 * Nx] + in_row[x - 3 * Nx] +
+                                             in_row[x + 3 * Nxy] + in_row[x - 3 * Nxy]);
